fun test_ceiling() {
    let a = from_quotient(101, 100);
    assert!(a.ceil() == 2);

    let a = from_raw(1);
    assert!(a.ceil() == 1);
}

#[test]
fun test_floor() {
    let a = from_quotient(101, 100);
    assert!(a.floor() == 1);

    let a = from_raw(1);
    assert!(a.floor() == 0);
}

